page Sim "/" {
  meta title="Simulación de pelotas"

  state count = 0
  state frames = 0
  state paused = false

  ref box
  ref balls
  ref raf

  fn makeBall() {
    let r = 10
    return {
      x: r + Math.random() * (400 - 2 * r),
      y: r + Math.random() * (300 - 2 * r),
      vx: (Math.random() * 2 - 1) * 3,
      vy: (Math.random() * 2 - 1) * 3,
      r: r
    }
  }

  fn clamp(b) {
    if b.x < b.r {
      b.x = b.r
      b.vx = Math.abs(b.vx)
    }
    if b.x > 400 - b.r {
      b.x = 400 - b.r
      b.vx = -Math.abs(b.vx)
    }
    if b.y < b.r {
      b.y = b.r
      b.vy = Math.abs(b.vy)
    }
    if b.y > 300 - b.r {
      b.y = 300 - b.r
      b.vy = -Math.abs(b.vy)
    }
  }

  fn physics() {
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      clamp(b)
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let b = balls[j]
        let dx = b.x - a.x
        let dy = b.y - a.y
        let minD = a.r + b.r
        let d2 = dx * dx + dy * dy
        if d2 < minD * minD {
          let d = Math.sqrt(d2) || 0.01
          let nx = d2 > 0 ? dx / d : 1
          let ny = d2 > 0 ? dy / d : 0
          let overlap = minD - d
          a.x -= nx * overlap / 2
          a.y -= ny * overlap / 2
          b.x += nx * overlap / 2
          b.y += ny * overlap / 2
          if (b.vx - a.vx) * nx + (b.vy - a.vy) * ny < 0 {
            let tx = a.vx
            let ty = a.vy
            a.vx = b.vx
            a.vy = b.vy
            b.vx = tx
            b.vy = ty
          }
          clamp(a)
          clamp(b)
        }
      }
    }
  }

  fn draw() {
    if !box { return }
    let ctx = box.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#2563eb"
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn step() {
    if paused { return }
    physics()
    draw()
    frames++
    raf = requestAnimationFrame(step)
  }

  fn add() {
    balls.push(makeBall())
    count = balls.length
    if paused { draw() }
  }

  fn toggle() {
    paused = !paused
    if paused {
      cancelAnimationFrame(raf)
    } else {
      raf = requestAnimationFrame(step)
    }
  }

  fn reset() {
    let list = []
    for (let i = 0; i < 5; i++) {
      list.push(makeBall())
    }
    balls = list
    count = balls.length
    frames = 0
    draw()
  }

  mount {
    reset()
    raf = requestAnimationFrame(step)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 align=start {
    title "Simulación de pelotas" tag=h1
    canvas ref=box id="sim" width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      button "Agregar" primary -> add()
      button `${paused ? "Reanudar" : "Pausar"}` -> toggle()
      button "Reiniciar" -> reset()
    }
    row gap=4 {
      text `Pelotas: ${count}`
      text `Cuadros: ${frames}`
    }
  }
}

