import { useCallback, useEffect, useRef, useState } from "react";

const WIDTH = 400;
const HEIGHT = 300;
const RADIUS = 10;
const GRAVITY = 0.2;
const INITIAL_BALLS = 5;

type Ball = {
  x: number;
  y: number;
  vx: number;
  vy: number;
  color: string;
};

const COLORS = ["#ef4444", "#3b82f6", "#22c55e", "#eab308", "#a855f7", "#f97316", "#14b8a6", "#ec4899"];

function randomBall(existing: Ball[]): Ball {
  let x = 0;
  let y = 0;
  for (let attempt = 0; attempt < 50; attempt++) {
    x = RADIUS + Math.random() * (WIDTH - 2 * RADIUS);
    y = RADIUS + Math.random() * (HEIGHT - 2 * RADIUS);
    const overlaps = existing.some((b) => Math.hypot(b.x - x, b.y - y) < 2 * RADIUS);
    if (!overlaps) break;
  }
  return {
    x,
    y,
    vx: (Math.random() * 2 - 1) * 4,
    vy: (Math.random() * 2 - 1) * 4,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

function createBalls(n: number): Ball[] {
  const balls: Ball[] = [];
  for (let i = 0; i < n; i++) balls.push(randomBall(balls));
  return balls;
}

function step(balls: Ball[]) {
  // Gravedad y movimiento
  for (const b of balls) {
    b.vy += GRAVITY;
    b.x += b.vx;
    b.y += b.vy;

    // Rebote contra bordes
    if (b.x - RADIUS < 0) {
      b.x = RADIUS;
      b.vx = Math.abs(b.vx);
    } else if (b.x + RADIUS > WIDTH) {
      b.x = WIDTH - RADIUS;
      b.vx = -Math.abs(b.vx);
    }
    if (b.y - RADIUS < 0) {
      b.y = RADIUS;
      b.vy = Math.abs(b.vy);
    } else if (b.y + RADIUS > HEIGHT) {
      b.y = HEIGHT - RADIUS;
      b.vy = -Math.abs(b.vy);
    }
  }

  // Colisiones entre pelotas
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const dist = Math.hypot(dx, dy);
      if (dist < 2 * RADIUS) {
        // Separar para evitar que queden pegadas
        const nx = dist === 0 ? 1 : dx / dist;
        const ny = dist === 0 ? 0 : dy / dist;
        const overlap = 2 * RADIUS - dist;
        a.x -= (nx * overlap) / 2;
        a.y -= (ny * overlap) / 2;
        b.x += (nx * overlap) / 2;
        b.y += (ny * overlap) / 2;

        // Intercambiar velocidades si se están acercando
        const relVel = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
        if (relVel < 0 || dist === 0) {
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = b.vx;
          a.vy = b.vy;
          b.vx = tvx;
          b.vy = tvy;
        }
      }
    }
  }

  // Asegurar que ninguna pelota quede fuera del canvas tras separar
  for (const b of balls) {
    b.x = Math.min(Math.max(b.x, RADIUS), WIDTH - RADIUS);
    b.y = Math.min(Math.max(b.y, RADIUS), HEIGHT - RADIUS);
  }
}

function draw(canvas: HTMLCanvasElement | null, balls: Ball[]) {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, WIDTH, HEIGHT);
  ctx.fillStyle = "#f8fafc";
  ctx.fillRect(0, 0, WIDTH, HEIGHT);
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, RADIUS, 0, Math.PI * 2);
    ctx.fillStyle = b.color;
    ctx.fill();
    ctx.strokeStyle = "#1e293b";
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const ballsRef = useRef<Ball[] | null>(null);
  if (ballsRef.current === null) ballsRef.current = createBalls(INITIAL_BALLS);
  const framesRef = useRef(0);

  const [paused, setPaused] = useState(false);
  const [ballCount, setBallCount] = useState(INITIAL_BALLS);
  const [frames, setFrames] = useState(0);

  // Dibujo inicial
  useEffect(() => {
    draw(canvasRef.current, ballsRef.current!);
  }, []);

  // Bucle de animación
  useEffect(() => {
    if (paused) return;
    let id = 0;
    const loop = () => {
      const balls = ballsRef.current!;
      step(balls);
      draw(canvasRef.current, balls);
      framesRef.current += 1;
      setFrames(framesRef.current);
      id = requestAnimationFrame(loop);
    };
    id = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(id);
  }, [paused]);

  const handleAdd = useCallback(() => {
    const balls = ballsRef.current!;
    balls.push(randomBall(balls));
    setBallCount(balls.length);
    if (paused) draw(canvasRef.current, balls);
  }, [paused]);

  const handleTogglePause = useCallback(() => {
    setPaused((p) => !p);
  }, []);

  const handleReset = useCallback(() => {
    ballsRef.current = createBalls(INITIAL_BALLS);
    framesRef.current = 0;
    setFrames(0);
    setBallCount(INITIAL_BALLS);
    draw(canvasRef.current, ballsRef.current);
  }, []);

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col items-center justify-center gap-4 p-6">
      <h1 className="text-2xl font-bold text-slate-800">Simulación de pelotas</h1>
      <canvas
        id="sim"
        ref={canvasRef}
        width={WIDTH}
        height={HEIGHT}
        className="border-2 border-slate-700 rounded shadow bg-slate-50"
      />
      <div className="flex gap-2">
        <button
          onClick={handleAdd}
          className="px-4 py-2 rounded bg-blue-600 text-white font-medium hover:bg-blue-700"
        >
          Agregar
        </button>
        <button
          onClick={handleTogglePause}
          className="px-4 py-2 rounded bg-amber-500 text-white font-medium hover:bg-amber-600"
        >
          {paused ? "Reanudar" : "Pausar"}
        </button>
        <button
          onClick={handleReset}
          className="px-4 py-2 rounded bg-rose-600 text-white font-medium hover:bg-rose-700"
        >
          Reiniciar
        </button>
      </div>
      <div className="flex gap-6 text-slate-700 font-mono">
        <span>Pelotas: {ballCount}</span>
        <span>Cuadros: {frames}</span>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";

const W = 400;
const H = 300;
const R = 10;
const G = 0.2;

type Ball = { x: number; y: number; vx: number; vy: number; color: string };

const COLORS = ["#ef4444", "#3b82f6", "#22c55e", "#eab308", "#a855f7", "#ec4899", "#14b8a6", "#f97316"];

function randomBall(existing: Ball[]): Ball {
  let x = 0;
  let y = 0;
  for (let attempt = 0; attempt < 100; attempt++) {
    x = R + Math.random() * (W - 2 * R);
    y = R + Math.random() * (H - 2 * R);
    const overlaps = existing.some((b) => Math.hypot(b.x - x, b.y - y) < 2 * R);
    if (!overlaps) break;
  }
  return {
    x,
    y,
    vx: (Math.random() * 2 - 1) * 4,
    vy: (Math.random() * 2 - 1) * 4,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

function makeBalls(n: number): Ball[] {
  const arr: Ball[] = [];
  for (let i = 0; i < n; i++) arr.push(randomBall(arr));
  return arr;
}

function clampBall(b: Ball) {
  if (b.x < R) {
    b.x = R;
    b.vx = Math.abs(b.vx);
  } else if (b.x > W - R) {
    b.x = W - R;
    b.vx = -Math.abs(b.vx);
  }
  if (b.y < R) {
    b.y = R;
    b.vy = Math.abs(b.vy);
  } else if (b.y > H - R) {
    b.y = H - R;
    b.vy = -Math.abs(b.vy);
  }
}

function step(balls: Ball[]) {
  for (const b of balls) {
    b.vy += G;
    b.x += b.vx;
    b.y += b.vy;
    clampBall(b);
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i];
      const b = balls[j];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      let dist = Math.hypot(dx, dy);
      if (dist < 2 * R) {
        let nx: number;
        let ny: number;
        if (dist === 0) {
          nx = 1;
          ny = 0;
          dist = 0;
        } else {
          nx = dx / dist;
          ny = dy / dist;
        }
        // intercambiar velocidades solo si se acercan
        const relVel = (b.vx - a.vx) * nx + (b.vy - a.vy) * ny;
        if (relVel < 0 || dist === 0) {
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = b.vx;
          a.vy = b.vy;
          b.vx = tvx;
          b.vy = tvy;
        }
        // separar para que no queden superpuestas
        const overlap = (2 * R - dist) / 2;
        a.x -= nx * overlap;
        a.y -= ny * overlap;
        b.x += nx * overlap;
        b.y += ny * overlap;
        clampBall(a);
        clampBall(b);
      }
    }
  }
}

function draw(ctx: CanvasRenderingContext2D, balls: Ball[]) {
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = "#f8fafc";
  ctx.fillRect(0, 0, W, H);
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
    ctx.fillStyle = b.color;
    ctx.fill();
    ctx.strokeStyle = "#1e293b";
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const ballsRef = useRef<Ball[] | null>(null);
  if (ballsRef.current === null) ballsRef.current = makeBalls(5);
  const framesRef = useRef(0);

  const [running, setRunning] = useState(true);
  const [count, setCount] = useState(5);
  const [frames, setFrames] = useState(0);

  const redraw = useCallback(() => {
    const ctx = canvasRef.current?.getContext("2d");
    if (ctx && ballsRef.current) draw(ctx, ballsRef.current);
  }, []);

  useEffect(() => {
    redraw();
  }, [redraw]);

  useEffect(() => {
    if (!running) return;
    let id = 0;
    const loop = () => {
      const balls = ballsRef.current!;
      step(balls);
      redraw();
      framesRef.current += 1;
      setFrames(framesRef.current);
      id = requestAnimationFrame(loop);
    };
    id = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(id);
  }, [running, redraw]);

  const handleAdd = () => {
    const balls = ballsRef.current!;
    balls.push(randomBall(balls));
    setCount(balls.length);
    if (!running) redraw();
  };

  const handleToggle = () => setRunning((r) => !r);

  const handleReset = () => {
    ballsRef.current = makeBalls(5);
    framesRef.current = 0;
    setFrames(0);
    setCount(5);
    redraw();
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center gap-4 bg-slate-100 p-6">
      <h1 className="text-2xl font-bold text-slate-800">Simulación de pelotas</h1>
      <canvas
        id="sim"
        ref={canvasRef}
        width={W}
        height={H}
        className="border-2 border-slate-700 rounded shadow"
      />
      <div className="flex gap-2">
        <button
          onClick={handleAdd}
          className="px-4 py-2 rounded bg-blue-600 text-white hover:bg-blue-700"
        >
          Agregar
        </button>
        <button
          onClick={handleToggle}
          className="px-4 py-2 rounded bg-amber-500 text-white hover:bg-amber-600"
        >
          {running ? "Pausar" : "Reanudar"}
        </button>
        <button
          onClick={handleReset}
          className="px-4 py-2 rounded bg-red-600 text-white hover:bg-red-700"
        >
          Reiniciar
        </button>
      </div>
      <div className="flex gap-6 text-slate-700 font-mono">
        <span>Pelotas: {count}</span>
        <span>Cuadros: {frames}</span>
      </div>
    </div>
  );
}

