          const nx = dist === 0 ? 1 : dx / dist;
          const ny = dist === 0 ? 0 : dy / dist;
          // Separar para evitar que queden pegadas
          const overlap = (2 * R - dist) / 2;
          a.x -= nx * overlap;
          a.y -= ny * overlap;
          b.x += nx * overlap;
          b.y += ny * overlap;
          // Mantener dentro del canvas
          for (const p of [a, b]) {
            p.x = Math.min(Math.max(p.x, R), W - R);
            p.y = Math.min(Math.max(p.y, R), H - R);
          }
          // Intercambio de velocidades (colisión elástica, masas iguales)
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = b.vx;
          a.vy = b.vy;
          b.vx = tvx;
          b.vy = tvy;
        }
      }
    }
  };

  const draw = () => {
    const ctx = canvas?.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, W, H);
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
      ctx.closePath();
    }
  };

  const loop = () => {
    step();
    draw();
    setFrames((f) => f + 1);
    rafId = requestAnimationFrame(loop);
  };

  const start = () => {
    if (rafId === null) rafId = requestAnimationFrame(loop);
  };

  const stop = () => {
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
  };

  onMount(() => {
    draw();
    start();
  });

  onCleanup(() => stop());

  const add = () => {
    balls.push(randomBall(balls));
    setCount(balls.length);
    if (paused()) draw();
  };

  const togglePause = () => {
    if (paused()) {
      setPaused(false);
      start();
    } else {
      setPaused(true);
      stop();
    }
  };

  const reset = () => {
    balls = createBalls(INITIAL);
    setCount(balls.length);
    setFrames(0);
    draw();
  };

  return (
    <div class="min-h-screen flex flex-col items-center justify-center gap-4 bg-gray-100 p-4">
      <canvas
        id="sim"
        ref={canvas}
        width={W}
        height={H}
        class="border border-gray-400 bg-white rounded shadow"
      />
      <div class="flex gap-2">
        <button
          class="px-4 py-2 rounded bg-blue-600 text-white hover:bg-blue-700"
          onClick={add}
        >
          Agregar
        </button>
        <button
          class="px-4 py-2 rounded bg-yellow-500 text-white hover:bg-yellow-600"
          onClick={togglePause}
        >
          <Show when={paused()} fallback="Pausar">
            Reanudar
          </Show>
        </button>
        <button
          class="px-4 py-2 rounded bg-red-600 text-white hover:bg-red-700"
          onClick={reset}
        >
          Reiniciar
        </button>
      </div>
      <div class="flex gap-6 text-gray-800 font-mono">
        <span>Pelotas: {count()}</span>
        <span>Cuadros: {frames()}</span>
      </div>
    </div>
  );
}

import { createSignal, onCleanup, onMount } from "solid-js";

type Ball = {
  x: number;
  y: number;
  vx: number;
  vy: number;
  color: string;
};

const WIDTH = 400;
const HEIGHT = 300;
const RADIUS = 10;
const GRAVITY = 0.2;
const INITIAL_BALLS = 5;

const COLORS = [
  "#ef4444",
  "#f97316",
  "#eab308",
  "#22c55e",
  "#06b6d4",
  "#3b82f6",
  "#8b5cf6",
  "#ec4899",
];

function randomBetween(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

function createBall(existing: Ball[]): Ball {
  let x = randomBetween(RADIUS, WIDTH - RADIUS);
  let y = randomBetween(RADIUS, HEIGHT - RADIUS);
  // Intentar no superponer con pelotas existentes
  for (let attempt = 0; attempt < 50; attempt++) {
    const overlaps = existing.some((b) => {
      const dx = b.x - x;
      const dy = b.y - y;
      return dx * dx + dy * dy < (2 * RADIUS) * (2 * RADIUS);
    });
    if (!overlaps) break;
    x = randomBetween(RADIUS, WIDTH - RADIUS);
    y = randomBetween(RADIUS, HEIGHT - RADIUS);
  }
  let vx = randomBetween(-3, 3);
  let vy = randomBetween(-3, 3);
  if (Math.abs(vx) < 0.5) vx = vx < 0 ? -1 : 1;
  return {
    x,
    y,
    vx,
    vy,
    color: COLORS[Math.floor(Math.random() * COLORS.length)],
  };
}

function createBalls(n: number): Ball[] {
  const arr: Ball[] = [];
  for (let i = 0; i < n; i++) arr.push(createBall(arr));
  return arr;
}

function clampToBounds(b: Ball) {
  if (b.x < RADIUS) {
    b.x = RADIUS;
    b.vx = Math.abs(b.vx);
  } else if (b.x > WIDTH - RADIUS) {
    b.x = WIDTH - RADIUS;
    b.vx = -Math.abs(b.vx);
  }
  if (b.y < RADIUS) {
    b.y = RADIUS;
    b.vy = Math.abs(b.vy);
  } else if (b.y > HEIGHT - RADIUS) {
    b.y = HEIGHT - RADIUS;
    b.vy = -Math.abs(b.vy);
  }
}

export default function App() {
  let canvasRef: HTMLCanvasElement | undefined;
  let balls: Ball[] = createBalls(INITIAL_BALLS);
  let rafId: number | null = null;

  const [count, setCount] = createSignal(balls.length);
  const [frames, setFrames] = createSignal(0);
  const [paused, setPaused] = createSignal(false);

  const step = () => {
    // Gravedad y movimiento
    for (const b of balls) {
      b.vy += GRAVITY;
      b.x += b.vx;
      b.y += b.vy;
      clampToBounds(b);
    }

    // Colisiones entre pelotas (intercambio de velocidades)
    const minDist = 2 * RADIUS;
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i];
        const b = balls[j];
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const distSq = dx * dx + dy * dy;
        if (distSq < minDist * minDist) {
          const dist = Math.sqrt(distSq) || 0.0001;
          const nx = distSq === 0 ? 1 : dx / dist;
          const ny = distSq === 0 ? 0 : dy / dist;

          // Separar para que no queden superpuestas
          const overlap = (minDist - dist) / 2;
          a.x -= nx * overlap;
          a.y -= ny * overlap;
          b.x += nx * overlap;
          b.y += ny * overlap;

          // Intercambiar velocidades solo si se acercan
          const rvx = b.vx - a.vx;
          const rvy = b.vy - a.vy;
          if (rvx * nx + rvy * ny < 0) {
            const tvx = a.vx;
            const tvy = a.vy;
            a.vx = b.vx;
            a.vy = b.vy;
            b.vx = tvx;
            b.vy = tvy;
          }

          clampToBounds(a);
          clampToBounds(b);
        }
      }
    }
  };

  const draw = () => {
    if (!canvasRef) return;
    const ctx = canvasRef.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, WIDTH, HEIGHT);
    ctx.fillStyle = "#f8fafc";
    ctx.fillRect(0, 0, WIDTH, HEIGHT);
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, RADIUS, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
      ctx.strokeStyle = "#1e293b";
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  };

  const loop = () => {
    step();
    draw();
    setFrames((f) => f + 1);
    rafId = requestAnimationFrame(loop);
  };

  const start = () => {
    if (rafId === null) {
      rafId = requestAnimationFrame(loop);
    }
  };

  const stop = () => {
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
  };

  const handleAdd = () => {
    balls.push(createBall(balls));
    setCount(balls.length);
    if (paused()) draw();
  };

  const handleTogglePause = () => {
    if (paused()) {
      setPaused(false);
      start();
    } else {
      setPaused(true);
      stop();
    }
  };

  const handleReset = () => {
    balls = createBalls(INITIAL_BALLS);
    setCount(balls.length);
    setFrames(0);
    draw();
  };

  onMount(() => {
    draw();
    start();
  });

  onCleanup(() => {
    stop();
  });

  return (
    <div class="min-h-screen flex flex-col items-center justify-center gap-4 bg-slate-100 p-6">
      <h1 class="text-2xl font-bold text-slate-800">Simulación de pelotas</h1>
      <canvas
        id="sim"
        ref={canvasRef}
        width={WIDTH}
        height={HEIGHT}
        class="border border-slate-400 rounded shadow bg-slate-50"
      />
      <div class="flex gap-2">
        <button
          class="px-4 py-2 rounded bg-blue-600 text-white hover:bg-blue-700"
          onClick={handleAdd}
        >
          Agregar
        </button>
        <button
          class="px-4 py-2 rounded bg-amber-500 text-white hover:bg-amber-600"
          onClick={handleTogglePause}
        >
          {paused() ? "Reanudar" : "Pausar"}
        </button>
        <button
          class="px-4 py-2 rounded bg-slate-600 text-white hover:bg-slate-700"
          onClick={handleReset}
        >
          Reiniciar
        </button>
      </div>
      <div class="flex gap-6 text-slate-700 font-mono">
        <span>Pelotas: {count()}</span>
        <span>Cuadros: {frames()}</span>
      </div>
    </div>
  );
}
